private static NewReservation readNewReservation(Context ctx) {
    CreateReservationRequest body;
    try {
        body = ctx.bodyAsClass(CreateReservationRequest.class);
    } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
        throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
    }
    if (body == null
            || body.roomNumber() == null
            || isBlank(body.guestName())
            || isBlank(body.guestEmail())
            || body.checkIn() == null
            || body.checkOut() == null
            || body.guests() == null
            || body.ratePlan() == null) {
        throw new HotelException(ErrorCode.INVALID_REQUEST, "required fields are missing");
    }

    boolean hasIndividual = !isBlank(body.guestCpf());
    boolean hasCompany = !isBlank(body.companyCnpj()) && !isBlank(body.companyName());
    boolean hasForeign = !isBlank(body.guestPassport()) && !isBlank(body.guestCountry());

    int identificationCount = (hasIndividual ? 1 : 0) + (hasCompany ? 1 : 0) + (hasForeign ? 1 : 0);
    if (identificationCount != 1) {
        throw new HotelException(
                ErrorCode.INVALID_REQUEST,
                "guest must have exactly one identification: CPF, or CNPJ and company name, or passport and country");
    }

    Guest guest;
    if (hasIndividual) {
        guest = Guest.individual(body.guestName(), body.guestEmail(), body.guestCpf());
    } else if (hasCompany) {
        guest = Guest.company(body.guestName(), body.guestEmail(), body.companyCnpj(), body.companyName());
    } else {
        guest = Guest.foreign(body.guestName(), body.guestEmail(), body.guestPassport(), body.guestCountry());
    }

    return new NewReservation(
            body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
}

