package hotel.documents;

import hotel.reservations.Guest;
import hotel.reservations.NewReservation;
import hotel.reservations.Price;
import hotel.reservations.RatePlan;
import hotel.reservations.Reservation;
import hotel.rooms.Room;
import hotel.rooms.RoomType;
import java.math.BigDecimal;
import java.time.LocalDate;
import org.junit.jupiter.api.Test;

/** Examples showing the three types of documents generated. */
class DocumentTypesExampleTest {

    private final Room room = new Room(201, RoomType.DELUXE, 3, new BigDecimal("389.90"));
    private final LocalDate checkIn = LocalDate.of(2027, 3, 10);
    private final LocalDate checkOut = LocalDate.of(2027, 3, 12);
    private final Price price = new Price(2, new BigDecimal("779.80"), BigDecimal.ZERO, new BigDecimal("779.80"));

    @Test
    void individualReceiptExample() {
        Guest guest = Guest.individual("Carla Dias", "carla@example.com", "111.222.333-44");
        NewReservation request = new NewReservation(201, guest, checkIn, checkOut, 2, RatePlan.STANDARD);
        Reservation reservation = new Reservation(1L, request, price);

        ReservationDocument document = DocumentFactory.create(reservation, room);
        System.out.println("=== COMPROVANTE PESSOA FÍSICA ===");
        System.out.println(document.text());
    }

    @Test
    void companyInvoiceExample() {
        Guest guest = Guest.company("Ana Souza", "ana@example.com", "12.345.678/0001-90", "Tecnosul Ltda");
        NewReservation request = new NewReservation(201, guest, checkIn, checkOut, 1, RatePlan.STANDARD);
        Reservation reservation = new Reservation(3L, request, price);

        ReservationDocument document = DocumentFactory.create(reservation, room);
        System.out.println("=== FATURA EMPRESA ===");
        System.out.println(document.text());
    }

    @Test
    void bookingReceiptExample() {
        Guest guest = Guest.foreign("John Smith", "john@example.com", "X1234567", "United Kingdom");
        NewReservation request = new NewReservation(201, guest, checkIn, checkOut, 1, RatePlan.STANDARD);
        Reservation reservation = new Reservation(4L, request, price);

        ReservationDocument document = DocumentFactory.create(reservation, room);
        System.out.println("=== BOOKING RECEIPT (ESTRANGEIRO) ===");
        System.out.println(document.text());
    }
}

